package com.ajay.amusezone.controller;
import com.ajay.amusezone.entity.EntryTicket; import com.ajay.amusezone.repository.EntryTicketRepository; import org.springframework.web.bind.annotation.*; import java.util.List;
@RestController @RequestMapping("/api/tickets") public class TicketController {private final EntryTicketRepository r; public TicketController(EntryTicketRepository r){this.r=r;} @GetMapping public List<EntryTicket> all(){return r.findAll();} @GetMapping("/{id}") public EntryTicket get(@PathVariable Long id){return r.findById(id).orElseThrow(()->new RuntimeException("Ticket not found"));} @PostMapping public EntryTicket create(@RequestBody EntryTicket x){return r.save(x);} @PutMapping("/{id}") public EntryTicket update(@PathVariable Long id,@RequestBody EntryTicket x){x.setId(id);return r.save(x);} @DeleteMapping("/{id}") public void delete(@PathVariable Long id){r.deleteById(id);}}
